     8	import hotel.reservations.ReservationService;
     9	import hotel.reservations.ReservationStore;
    10	import hotel.rooms.Rooms;
    11	import hotel.web.HttpApi;
    12	import io.javalin.Javalin;
    13	import javax.sql.DataSource;
    14	
    15	/** Puts the inn's pieces together and runs the HTTP server. */
    16	public final class Hotel {
    17	
    18	    private final Javalin server;
    19	
    20	    public Hotel(DataSource dataSource) {
    21	        Rooms rooms = new Rooms(dataSource);
    22	        ReservationStore store = new ReservationStore(dataSource);
    23	        SentMessages sentMessages = new SentMessages(dataSource);
    24	        ReservationService reservations =
    25	                new ReservationService(rooms, store, new PriceCalculator(),
    26	                        new EmailSender(sentMessages, "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"))));
    27	        HttpApi api = new HttpApi(
    28	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    29	        this.server = api.server();
    30	    }
    31	
    32	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    33	    public int start(int port) {
    34	        server.start(port);
    35	        return server.port();
    36	    }
    37	
    38	    public void stop() {
    39	        server.stop();
    40	    }
    41	
    42	    public static void main(String[] args) {
    43	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    44	        Database database = new Database(System.getenv());
    45	        new Hotel(database.dataSource()).start(port);
    46	    }
    47	}
