     1	package hotel;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import java.util.Map;
     6	import javax.sql.DataSource;
     7	import org.flywaydb.core.Flyway;
     8	
     9	/**
    10	 * The connections to the inn's PostgreSQL: the address comes in DB_URL (jdbc:postgresql://host:port/database), the
    11	 * user in DB_USER and the password in DB_PASSWORD. Opening it brings the schema up to date with the migrations in
    12	 * src/main/resources/db/migration.
    13	 */
    14	public final class Database implements AutoCloseable {
    15	
    16	    private final HikariDataSource dataSource;
    17	
    18	    public Database(Map<String, String> environment) {
    19	        String url = environment.get("DB_URL");
    20	        if (url == null || url.isBlank()) {
    21	            throw new IllegalStateException("DB_URL is not set: it must hold the PostgreSQL address");
    22	        }
    23	        HikariConfig config = new HikariConfig();
    24	        config.setJdbcUrl(url);
    25	        config.setUsername(environment.get("DB_USER"));
    26	        config.setPassword(environment.get("DB_PASSWORD"));
    27	        this.dataSource = new HikariDataSource(config);
    28	        Flyway.configure().dataSource(dataSource).load().migrate();
    29	    }
    30	
    31	    public DataSource dataSource() {
    32	        return dataSource;
    33	    }
    34	
    35	    @Override
    36	    public void close() {
    37	        dataSource.close();
    38	    }
    39	}
=== src/main/java/hotel/messages/EmailSender.java
     1	package hotel.messages;
     2	
     3	import java.util.regex.Pattern;
     4	
     5	/**
     6	 * Sends e-mails to guests. Every e-mail is kept in the list of sent messages. An invalid address is blocked; in
     7	 * test mode everything goes to the test inbox; otherwise a copy goes to the archive.
     8	 */
     9	public final class EmailSender {
    10	
    11	    static final String ARCHIVE = "arquivo@pousadamarealta.com.br";
    12	    static final String TEST_INBOX = "testes@pousadamarealta.com.br";
    13	    private static final Pattern VALID_ADDRESS = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
    14	
    15	    private final SentMessages sentMessages;
    16	    private final boolean testMode;
    17	
    18	    public EmailSender(SentMessages sentMessages) {
    19	        this(sentMessages, false);
    20	    }
    21	
    22	    public EmailSender(SentMessages sentMessages, boolean testMode) {
    23	        this.sentMessages = sentMessages;
    24	        this.testMode = testMode;
    25	    }
    26	
    27	    public Message send(String to, String subject, String body) {
    28	        if (!VALID_ADDRESS.matcher(to).matches()) {
    29	            return sentMessages.add("EMAIL", to, subject, body, MessageStatus.BLOCKED);
    30	        }
    31	        if (testMode) {
    32	            return sentMessages.add("EMAIL", TEST_INBOX, "[TESTE] " + subject,
    33	                    "Destinatário original: " + to + "\n" + body, MessageStatus.SENT);
    34	        }
    35	        Message original = sentMessages.add("EMAIL", to, subject, body, MessageStatus.SENT);
    36	        sentMessages.add("EMAIL", ARCHIVE, "[Cópia] " + subject, body, MessageStatus.SENT);
    37	        return original;
    38	    }
    39	}
