=== src/main/java/hotel/messages/SentMessages.java
     1	package hotel.messages;
     2	
     3	import java.sql.Connection;
     4	import java.sql.PreparedStatement;
     5	import java.sql.ResultSet;
     6	import java.sql.SQLException;
     7	import java.util.ArrayList;
     8	import java.util.List;
     9	import javax.sql.DataSource;
    10	
    11	/** Every message the inn sent, so the front desk can check what each guest received. */
    12	public final class SentMessages {
    13	
    14	    private final DataSource dataSource;
    15	
    16	    public SentMessages(DataSource dataSource) {
    17	        this.dataSource = dataSource;
    18	    }
    19	
    20	    Message add(String channel, String to, String subject, String body, MessageStatus status) {
    21	        try (Connection connection = dataSource.getConnection();
    22	                PreparedStatement insert = connection.prepareStatement(
    23	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) "
    24	                                + "RETURNING id")) {
    25	            insert.setString(1, channel);
    26	            insert.setString(2, to);
    27	            insert.setString(3, subject);
    28	            insert.setString(4, body);
    29	            insert.setString(5, status.name());
    30	            try (ResultSet generated = insert.executeQuery()) {
    31	                generated.next();
    32	                return new Message(generated.getLong("id"), channel, to, subject, body, status);
    33	            }
    34	        } catch (SQLException failure) {
    35	            throw new IllegalStateException("could not keep the message to " + to, failure);
    36	        }
    37	    }
    38	
    39	    public List<Message> all() {
    40	        try (Connection connection = dataSource.getConnection();
    41	                PreparedStatement select = connection.prepareStatement(
    42	                        "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id");
    43	                ResultSet rows = select.executeQuery()) {
    44	            List<Message> messages = new ArrayList<>();
    45	            while (rows.next()) {
    46	                messages.add(new Message(
    47	                        rows.getLong("id"),
    48	                        rows.getString("channel"),
    49	                        rows.getString("recipient"),
    50	                        rows.getString("subject"),
    51	                        rows.getString("body"),
    52	                        MessageStatus.valueOf(rows.getString("status"))));
    53	            }
    54	            return messages;
    55	        } catch (SQLException failure) {
    56	            throw new IllegalStateException("could not read the sent messages", failure);
    57	        }
    58	    }
    59	}
=== src/main/java/hotel/documents/ReservationReceipt.java
     1	package hotel.documents;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.rooms.Room;
     5	import hotel.rooms.RoomType;
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	
     9	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
    10	public record ReservationReceipt(
    11	        String title,
    12	        long reservationId,
    13	        String guestName,
    14	        String guestCpf,
    15	        int roomNumber,
    16	        RoomType roomType,
    17	        LocalDate checkIn,
    18	        LocalDate checkOut,
    19	        int nights,
    20	        BigDecimal subtotal,
    21	        BigDecimal discount,
    22	        BigDecimal total) {
    23	
    24	    public ReservationReceipt(Reservation reservation, Room room) {
    25	        this(
    26	                "Comprovante de reserva",
    27	                reservation.id(),
    28	                reservation.guest().name(),
    29	                reservation.guest().cpf(),
    30	                room.number(),
    31	                room.type(),
    32	                reservation.checkIn(),
    33	                reservation.checkOut(),
    34	                reservation.price().nights(),
    35	                reservation.price().subtotal(),
    36	                reservation.price().discount(),
    37	                reservation.price().total());
    38	    }
    39	
    40	    public String text() {
    41	        StringBuilder text = new StringBuilder();
    42	        text.append(title).append(" nº ").append(reservationId).append('\n');
    43	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    44	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    45	        text.append("Entrada: ").append(TextFormat.date(checkIn))
    46	                .append(" | Saída: ").append(TextFormat.date(checkOut))
    47	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    48	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
    49	        if (discount.signum() > 0) {
    50	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
    51	        }
    52	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
    53	        return text.toString();
    54	    }
    55	}
